public class Singleton<T>{public static T Instance{get;set;}}
namespace UnityEngine{public class Object{public static bool operator==(Object a,Object b)=>ReferenceEquals(a,b);public static bool operator!=(Object a,Object b)=>!ReferenceEquals(a,b);public override bool Equals(object b)=>ReferenceEquals(this,b);public override int GetHashCode()=>System.Runtime.CompilerServices.RuntimeHelpers.GetHashCode(this);}public struct Vector3{public float x,y,z;public Vector3(float a,float b,float c){x=a;y=b;z=c;}}public struct Quaternion{public float x,y,z,w;}public class Transform:Object{public Vector3 position{get;set;}public Vector3 localPosition=>position;public Vector3 localEulerAngles{get;set;}public Quaternion localRotation{get;set;}public void Rotate(Vector3 v){localEulerAngles=new(localEulerAngles.x+v.x,localEulerAngles.y+v.y,localEulerAngles.z+v.z);}}}
namespace Studio{
 public interface ICommand{void Do();void Undo();void Redo();}public class ChangeAmount{public UnityEngine.Vector3 pos{get;set;}public UnityEngine.Vector3 rot{get;set;}}
 public class GuideObject:UnityEngine.Object{public bool enablePos{get;set;}=true;public int dicKey{get;set;}public ChangeAmount changeAmount{get;set;}=new();public UnityEngine.Transform transformTarget=new();}
 public class GuideObjectManager{public GuideObject[] selectObjects{get;set;}public GuideObject selectObject=>selectObjects?[0];public GuideObject operationTarget{get;set;}}
 public class UndoRedoManager{public List<ICommand> Commands=new();public void Push(ICommand c)=>Commands.Add(c);}
 public class GuideCommand{public class EqualsInfo{public int dicKey;public UnityEngine.Vector3 oldValue,newValue;}public static Dictionary<int,ChangeAmount> Amounts=new();public class MoveEqualsCommand:ICommand{public EqualsInfo[] changeAmountInfo;public MoveEqualsCommand(EqualsInfo[] x){changeAmountInfo=x;}public void Do()=>Redo();public void Redo(){foreach(var x in changeAmountInfo)Amounts[x.dicKey].pos=x.newValue;}public void Undo(){foreach(var x in changeAmountInfo)Amounts[x.dicKey].pos=x.oldValue;}}public class RotationEqualsCommand:ICommand{public EqualsInfo[] changeAmountInfo;public RotationEqualsCommand(EqualsInfo[] x){changeAmountInfo=x;}public void Do()=>Redo();public void Redo(){foreach(var x in changeAmountInfo)Amounts[x.dicKey].rot=x.newValue;}public void Undo(){foreach(var x in changeAmountInfo)Amounts[x.dicKey].rot=x.oldValue;}}}
}
